function drawBlocks(ctx, city, view) {
  for (let j = 0; j < 7; j += 1) {
    for (let i = 0; i < 9; i += 1) {
      const x = i * PITCH + ROAD_W;
      const y = j * PITCH + ROAD_W;
      const size = PITCH - ROAD_W;
      if (x + size < view.x || x > view.x + view.w || y + size < view.y || y > view.y + view.h) continue;
