        if (player.punchAnim > 0) {
          ctx.save();
          ctx.translate(player.x, player.y);
          ctx.rotate(player.angle);
          ctx.strokeStyle = 'rgba(255,255,255,0.8)';
          ctx.lineWidth = 5;
          ctx.beginPath();
          ctx.arc(20, 0, 14, -0.9, 0.9);
          ctx.stroke();
          ctx.restore();
