    drawPaused(game) {
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(0, 0, viewW, viewH);
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ffd23a';
      ctx.font = 'bold 56px system-ui, sans-serif';
      ctx.fillText('PAUSED', viewW / 2, viewH / 2);
